class LRUCache:
    """A Least Recently Used (LRU) Cache that implements O(1) get and put methods using a combination of a fixed-size array for keys and values, alongside a hashmap for fast access and tracking usage order."""

    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}
        self.keys = []

    def get(self, key: int) -> int:
        """Return the value of the key if present, otherwise return -1."""
        if key in self.cache:
            self.keys.remove(key)
            self.keys.insert(0, key)  # Move to front to indicate recent usage
            return self.cache[key]
        return -1

    def put(self, key: int, value: int) -> None:
        """Add a key-value pair to the cache."""
        if key in self.cache:
            self.keys.remove(key)  # Remove the old key position
        elif len(self.cache) >= self.capacity:
            # Evict the least recently used key
            lru_key = self.keys.pop()  # Remove from end of the list
            del self.cache[lru_key]  # Remove from cache

        self.keys.insert(0, key)  # Insert the new key at the front
        self.cache[key] = value  # Update the value

class LRUCache:
    """A Least Recently Used (LRU) Cache that implements O(1) get and put methods using a combination of a hashmap and a fixed-size list for tracking the order of usage."""

    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}
        self.order = []

    def get(self, key: int) -> int:
        """Return the value of the key if present, otherwise return -1."""
        if key in self.cache:
            # Move the key to the front of the order list
            self.order.remove(key)
            self.order.insert(0, key)
            return self.cache[key]
        return -1

    def put(self, key: int, value: int) -> None:
        """Add a key-value pair to the cache."""
        if key in self.cache:
            # Update the value and move the key to the front
            self.cache[key] = value
            self.order.remove(key)
        else:
            if len(self.cache) >= self.capacity:
                # Evict the least recently used key
                lru_key = self.order.pop()
                del self.cache[lru_key]
            self.cache[key] = value

        self.order.insert(0, key)  # Add the new key to the front of the order list

class LRUCache:
    """A Least Recently Used (LRU) Cache that uses a hashmap for O(1) access and a simple list to maintain the order of access, focusing on efficiency for both get and put operations."""

    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}
        self.access_order = []

    def get(self, key: int) -> int:
        """Return the value of the key if present, otherwise return -1."""
        if key in self.cache:
            # Move the accessed key to the end to indicate recent use
            self.access_order.remove(key)
            self.access_order.append(key)
            return self.cache[key]
        return -1

    def put(self, key: int, value: int) -> None:
        """Add a key-value pair to the cache."""
        if key in self.cache:
            # Update the value and mark it as recently used
            self.cache[key] = value
            self.access_order.remove(key)
            self.access_order.append(key)
        else:
            if len(self.cache) >= self.capacity:
                # Remove the least recently used key
                lru_key = self.access_order.pop(0)  # Remove from the front (oldest)
                del self.cache[lru_key]
            # Insert the new key-value pair
            self.cache[key] = value
            self.access_order.append(key)
